Rules.InvariantScript:
UpdateContext(
    {
        var_visiblePainelAeronave: false,
        var_visiblePainelVeiculo: false,
        var_visiblePainelPessoa: false,
        var_visiblePainelSpiner: true,
        var_tipoEnvolvido: "",
        //Default color border
        varBordaDefault: RGBA(
            0,
            0,
            0,
            1
        )
    }
)

Clear(col_incPistaImg);         
Clear(col_incPistaEnvolvidos);                      
Reset(cmbIncPistaHoraCadastro);
Reset(cmbIncPistaMinuCadastro);
Reset(cmbIncPistaAcaoEva1);
Reset(cmbIncPistaAcaoEvaVeiculo);
Reset(cmbIncPistaCondMeteor);
Reset(cmbIncPistaCondPista);
Reset(cmbIncPistaSelecEva1);
Reset(cmbIncPistaSelecEvaVeiculo);
Reset(TxtIncPistaDescOcorrencia);
Reset(TxtIncPistaDescEvaOutros1);
Reset(TxtIncPistaDescEvaOutrosVeiculo);
Reset(TxtIncPistaDisCab1);
Reset(TxtIncPistaDisPer1);
Reset(TxtIncPistaLocal);
Reset(TxtIncPistaMatAero1);
Reset(TxtIncPistaPessoaColete);
Reset(TxtIncPistaPessoaEmpresa);
Reset(TxtIncPistaPessoaNome);
Reset(TxtIncPistaTeto);
Reset(TxtIncPistaVeiCod);
Reset(TxtIncPistaVeiEmpresa);
Reset(TxtIncPistaVeiLocal);
Reset(TxtIncPistaVeiMapa);
Reset(TxtIncPistaVisibi);
Reset(TxtIncPistaDistVertical);
Reset(TxtIncPistaDistHorizontal);
Reset(cmbIncPistaAtsVeiculo);
Reset(cmbIncPistaAtsPessoa);
UpdateContext(
    {
        //Default color border
        varBordaDefault: RGBA(
            0,
            0,
            0,
            1
        )
    }
);

UpdateContext(
    {
        varDisplayAcaoEvasiva: DisplayMode.Disabled,
        varDisplayAcaoEvasivaOutros: DisplayMode.Disabled,

        varDisplayAcaoEvasivaVeiculo: DisplayMode.Disabled,
        varDisplayAcaoEvasivaOutrosVeiculo: DisplayMode.Disabled,

        varDisplayAcaoEvasivaPessoa: DisplayMode.Disabled,
        varDisplayAcaoEvasivaOutrosPessoa: DisplayMode.Disabled
    }
)

Reset(cmbIncPistaSelecEva1);
Reset(TxtIncPistaDescEvaOutros1);
Reset(TxtIncPistaDisCab1);
Reset(TxtIncPistaDisPer1);
Reset(TxtIncPistaMatAero1);
Reset(TxtIncPistaAeroLocal);
Reset(TxtIncPistaAeroMapa);
Reset(cmbIncPistaAcaoEva1);

Reset(cmbIncPistaAcaoEvaVeiculo);
Reset(cmbIncPistaSelecEvaVeiculo);
Reset(TxtIncPistaDescEvaOutrosVeiculo);
Reset(TxtIncPistaVeiCod);
Reset(TxtIncPistaVeiEmpresa);
Reset(TxtIncPistaVeiLocal);
Reset(TxtIncPistaVeiMapa);
Reset(cmbIncPistaAtsVeiculo);


Reset(TxtIncPistaPessoaColete);
Reset(TxtIncPistaPessoaEmpresa);
Reset(TxtIncPistaPessoaNome);
Reset(cmbIncPistaAtsPessoa);
Reset(cmbIncPistaAcaoEvaPessoa);
Reset(cmbIncPistaSelecEvaPessoa);
Reset(TxtIncPistaDescEvaOutrosPessoa);
Reset(TxtIncPistaPessoaLocal);
Reset(TxtIncPistaPessoaMapa)

UpdateContext(
    {
        var_visiblePainelAeronave: true,
        var_visiblePainelVeiculo: false,
        var_visiblePainelPessoa: false,
        var_visiblePainelSpiner: false,
        var_tipoEnvolvido: "Aeronave"
    }
);
Select(ButtonResetFormIncPistaEnvolvidos)

UpdateContext(
    {
        var_visiblePainelAeronave: false,
        var_visiblePainelVeiculo: true,
        var_visiblePainelPessoa: false,
        var_visiblePainelSpiner: false,
        var_tipoEnvolvido: "Veiculo"
    }
);
Select(ButtonResetFormIncPistaEnvolvidos)

UpdateContext(
    {
        var_visiblePainelAeronave: false,
        var_visiblePainelVeiculo: false,
        var_visiblePainelPessoa: true,
        var_visiblePainelSpiner: false,
        var_tipoEnvolvido: "Pessoa"
    }
);
Select(ButtonResetFormIncPistaEnvolvidos)

UpdateContext(
    {
        var_visiblePainelAeronave: false,
        var_visiblePainelVeiculo: true,
        var_visiblePainelPessoa: false
    }
)

If(
    IsBlank(AddMediaButtonImgCadastrar.Media) = false,
    Collect(
        col_incPistaImg,
        {
            id: Value(
                First(
                    SortByColumns(
                        Filter(
                            col_incPistaImg,
                            id >= 0
                        ),
                        "id",
                        SortOrder.Descending
                    )
                ).id + 1
            ),
            img: UploadedImageCadastrar.Image
        }
    )
);
Reset(AddMediaButtonImgCadastrar)

UpdateContext(
    {
        var_visibleSpiner: true,
        var_formErro: false,
        var_incPistaId: Value(
            First(
                SortByColumns(
                    Filter(
                        '14.3-tbl_IncPista',
                        incPista_id > 0
                    ),
                    "ID",
                    SortOrder.Descending
                )
            ).incPista_id + 1
        )
    }
);
Switch(
    true,
    IsBlank(cmbIncPistaAgravante.Selected.Value) = true,
    UpdateContext(
        {
            var_formErro: true,
            varBordaDefault: Color.Red
        }
    ),
    IsBlank(cmbIncPistaHoraCadastro.Selected.Value) = true,
    UpdateContext(
        {
            var_formErro: true,
            varBordaDefault: Color.Red
        }
    ),
    IsBlank(cmbIncPistaMinuCadastro.Selected.Value) = true,
    UpdateContext(
        {
            var_formErro: true,
            varBordaDefault: Color.Red
        }
    ),
    IsBlank(TxtIncPistaLocal.Text) = true,
    UpdateContext(
        {
            var_formErro: true,
            varBordaDefault: Color.Red
        }
    ),
    IsBlank(cmbIncPistaCondPista.Selected) = true,
    UpdateContext(
        {
            var_formErro: true,
            varBordaDefault: Color.Red
        }
    ),
    IsBlank(cmbIncPistaCondMeteor.Selected.Value) = true,
    UpdateContext(
        {
            var_formErro: true,
            varBordaDefault: Color.Red
        }
    ),
    IsBlank(TxtIncPistaTeto.Text) = true,
    UpdateContext(
        {
            var_formErro: true,
            varBordaDefault: Color.Red
        }
    ),
    IsBlank(TxtIncPistaVisibi.Text) = true,
    UpdateContext(
        {
            var_formErro: true,
            varBordaDefault: Color.Red
        }
    ),
    IsBlank(TxtIncPistaDistVertical.Text) = true,
    UpdateContext(
        {
            var_formErro: true,
            varBordaDefault: Color.Red
        }
    ),
    IsBlank(TxtIncPistaDistHorizontal.Text) = true,
    UpdateContext(
        {
            var_formErro: true,
            varBordaDefault: Color.Red
        }
    ),
    IsBlank(TxtIncPistaDescOcorrencia.Text) = true,
    UpdateContext(
        {
            var_formErro: true,
            varBordaDefault: Color.Red
        }
    ),
    CountRows(col_incPistaImg) = 0,
    UpdateContext(
        {
            var_formErro: true,
            varBordaDefault: Color.Red
        }
    ),
    CountRows(col_incPistaEnvolvidos) = 0,
    UpdateContext(
        {
            var_formErro: true,
            varBordaDefault: Color.Red
        }
    ),
    UpdateContext(
        {var_formErro: false
            //;varBordaDefault: Color.Red
}
    )
);
If(
    var_formErro = true,
    Notify(
        "Atenção todas as informações devem ser preenchidas!",
        NotificationType.Error
    ),
    //Insert de dados no database------------------------------------------------------------------------------
    Patch(
        '14.3-tbl_IncPista',
        Defaults('14.3-tbl_IncPista'),
        {
            incPista_id: var_incPistaId,
            incPista_data: dtpIncPistaDataCadastro.SelectedDate,
            incPista_hora: cmbIncPistaHoraCadastro.Selected.Value & ":" & cmbIncPistaMinuCadastro.Selected.Value,
            incPista_localOcorrencia: TxtIncPistaLocal.Text,
            incPista_descOcorrencia: TxtIncPistaDescOcorrencia.Text,
            incPista_condPista: cmbIncPistaCondPista.Selected.Value,
            incPista_condMeteor: cmbIncPistaCondMeteor.Selected.Value,
            incPista_condTeto: TxtIncPistaTeto.Text,
            incPista_condVisib: TxtIncPistaVisibi.Text,
            incPista_distVertical: TxtIncPistaDistVertical.Text,
            incPista_distHorizontal: TxtIncPistaDistHorizontal.Text,
            incPista_bloco: varBlocoUser,
            incPista_aeroporto: varAeroUser,
            Agravante: cmbIncPistaAgravante.Selected.Value
        }
    );
    //insert dos envolvidos
ForAll(
        col_incPistaEnvolvidos,
        Patch(
            '14.3-tbl_IncPistaEnvolvidos',
            Defaults('14.3-tbl_IncPistaEnvolvidos'),
            {
                incPistaEnv_idOcorrencia: var_incPistaId,
                incPistaEnv_tipo: tipo,
                incPistaEnv_matricula: aer_matricula,
                incPistaEnv_acaoEvasiva: aer_acaoEvasiva & vei_acaoEvasiva & pes_acaoEvasiva,
                incPistaEnv_selectAcao: aer_selectAcao & vei_selectAcao & pes_selectAcao,
                incPistaEnv_distPerc: aer_distPercorrida,
                incPistaEnv_distCabec: aer_distCabeceira,
                incPistaEnv_locAcao: aer_localAcao & vei_localAcao & pes_localAcao,
                incPistaEnv_mapGrad: aer_mapaGrade.Text & vei_mapaGrade.Text & pes_mapaGrade.Text,
                incPistaEnv_outraAcao: aer_outraAcao & vei_outraAcao & pes_outraAcao,
                incPistaEnv_codigo: vei_codigo,
                incPistaEnv_empresa: vei_empresa & pes_empresa,
                incPistaEnv_contatoAts: vei_ats & pes_ats,
                incPistaEnv_nome: pes_nome,
                incPistaEnv_colete: pes_colete
            }
        )
    );
    //insert das imagens
ForAll(
        col_incPistaImg,
        Patch(
            '14.3-tbl_IncPistaImg',
            Defaults('14.3-tbl_IncPistaImg'),
            {
                incPistaImg_idOcorrencia: var_incPistaId,
                incPistaImg_imagem: img
            }
        )
    );
    Select(ButtonResetFormIncPista);
    Navigate(
        ScreenSucesso,
        ScreenTransition.Fade,
        {var_navigateSucess: ScreenIncursaoPista}
    )
);
UpdateContext({var_visibleSpiner: false});
